  const error=!value?t('tagNameRequired'):dictionaryTagCatalog().some(x=>x.id!==id&&x.translations.some(tr=>tr.language_tag===locale&&tr.name.normalize('NFKC').toLowerCase()===normal))?t('tagNameDuplicate'):'';
