 if(action==='filter:dictionary-kanji'){e.stopImmediatePropagation();dictionaryKanjiDraft=[...dictionaryKanjiIds];materialKanjiQuery='';materialKanjiSearchOpen=false;materialKanjiSelectedOnly=false;materialKanjiPanel=null;materialKanjiFilters={jlpt:null,radical:null,strokes:null};go('dictionary-kanji');return;}
 if(action==='clear-dictionary-kanji'){e.stopImmediatePropagation();dictionaryKanjiIds=[];render();return;}
 if(screen==='dictionary-kanji'){
  if(b.hasAttribute('data-dictionary-kanji-apply')){e.stopImmediatePropagation();dictionaryKanjiIds=[...dictionaryKanjiDraft];go('dictionary');return;}
  const [kind,value,extra]=action.split(':');
  if(handleMaterialReferenceAction(kind,value,extra)){e.stopImmediatePropagation();return;}
  if(kind==='kanji-view'){e.stopImmediatePropagation();materialKanjiSelectedOnly=value==='selected';render();document.querySelector('.material-selection-view')?.focus({preventScroll:true});return;}
  if(kind==='select-kanji'||b.hasAttribute('data-material-selection-clear')){e.stopImmediatePropagation();const id=Number(value),scroll=document.querySelector('.recipe-source-content')?.scrollTop||0;dictionaryKanjiDraft=kind==='select-kanji'?(dictionaryKanjiDraft.includes(id)?dictionaryKanjiDraft.filter(n=>n!==id):[...dictionaryKanjiDraft,id]):[];render();document.querySelector('.recipe-source-content').scrollTop=scroll;document.querySelector(`[data-action="${action}"]`)?.focus({preventScroll:true});return;}
 }
 if(action==='filter:dictionary-tags'||b.dataset.dictionaryTags){e.stopImmediatePropagation();const mode=b.dataset.dictionaryTags||'filter';if(mode==='manage'){closeDictionaryTagMenu();dictionaryTagsMode='manage';dictionaryTagQuery='';dictionaryTagSearchOpen=false;go('dictionary-tags');}else beginDictionaryTagSelection(mode);return;}
